// Generated by vibelang from src/flow/internal/Pending.ts; the migrate flow writes it again with each batch.
/**
 * Unresolved checkpoints survive every retry until operator recovery.
 *
 * @since 1.0.0-rc.0
 * @private
 */
import * as Effect from "effect/Effect";
import * as FileSystem from "effect/FileSystem";
import * as Option from "effect/Option";
import * as Path from "effect/Path";
import * as Fs from "../../internal/Fs.js";
import { io, make } from "../../MigrateError.js";
/**
 * Checks presence without trusting or replacing a possibly incomplete record.
 *
 * @since 1.0.0-rc.0
 * @private
 */
export const assertClear = (reportDirectory) => Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem;
    const path = yield* Path.Path;
    const file = path.join(reportDirectory, "pending-unit.json");
    const found = yield* Fs.optionalNotFound(fs.stat(file)).pipe(Effect.mapError(io(`could not inspect the pending checkpoint ${file}`)));
    if (Option.isNone(found))
        return;
    return yield* Effect.fail(make("checkpoint-failed", `an earlier migration has an unresolved checkpoint at ${file}`, `inspect that recovery record and restore its checkpoint; verify the recovered project, then remove only ${file} and rerun. Keep its backups until recovery is complete. Choosing another report directory does not clear the checkpoint.`));
});
